{"path": "style.css", "content": "/* 抽烟小助手 - 样式文件 */

/* 基础样式重置 */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Noto Sans SC', sans-serif;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    min-height: 100vh;
    padding: 20px;
    color: #333;
}

.app-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

/* 头部样式 */
.app-header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 30px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    text-align: center;
}

.header-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
}

.app-header i {
    font-size: 3rem;
    margin-bottom: 10px;
    opacity: 0.9;
}

.app-header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin: 0;
}

.header-subtitle {
    font-size: 1.1rem;
    opacity: 0.9;
    font-weight: 300;
}

/* 统计卡片区域 */
.stats-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 25px;
    margin-bottom: 30px;
}

.stat-card {
    background: white;
    padding: 25px;
    border-radius: 15px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
    text-align: center;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    border: 1px solid rgba(255, 255, 255, 0.2);
}

.stat-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.12);
}

.stat-icon {
    font-size: 2.5rem;
    color: #667eea;
    margin-bottom: 15px;
}

.stat-card h3 {
    font-size: 1rem;
    color: #666;
    margin-bottom: 10px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.stat-value {
    font-size: 2.8rem;
    font-weight: 700;
    color: #333;
    line-height: 1;
    margin: 10px 0;
}

.stat-unit {
    font-size: 0.9rem;
    color: #888;
    font-weight: 400;
}

/* 操作按钮 */
.actions-container {
    display: flex;
    gap: 20px;
    margin-bottom: 30px;
    justify-content: center;
    flex-wrap: wrap;
}

.btn-primary, .btn-secondary, .btn-settings {
    padding: 18px 35px;
    border: none;
    border-radius: 12px;
    font-size: 1.1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-width: 200px;
}

.btn-primary {
    background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
    color: white;
    box-shadow: 0 5px 15px rgba(245, 87, 108, 0.3);
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(245, 87, 108, 0.4);
}

.btn-primary:active {
    transform: translateY(-1px);
}

.btn-secondary {
    background: white;
    color: #666;
    border: 2px solid #e0e0e0;
}

.btn-secondary:hover {
    background: #f8f9fa;
    border-color: #667eea;
    color: #667eea;
}

/* 设置区域 */
.settings-container {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 30px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}

.settings-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 25px;
    color: #667eea;
}

.settings-header i {
    font-size: 1.5rem;
}

.settings-header h3 {
    font-size: 1.3rem;
    font-weight: 600;
}

.settings-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 25px;
}

.setting-item {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.setting-item label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 500;
    color: #555;
}

.setting-item label i {
    color: #667eea;
}

.input-group {
    display: flex;
    align-items: center;
    gap: 10px;
}

.input-group input {
    flex: 1;
    padding: 12px 15px;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.input-group input:focus {
    outline: none;
    border-color: #667eea;
}

.input-unit {
    color: #888;
    font-size: 0.9rem;
    min-width: 60px;
}

.btn-settings {
    background: #667eea;
    color: white;
    padding: 12px 25px;
    border-radius: 8px;
    align-self: flex-end;
    min-width: auto;
}

.btn-settings:hover {
    background: #5a6fd8;
}

/* 历史记录 */
.history-container {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 30px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}

.history-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 20px;
    color: #667eea;
}

.history-header i {
    font-size: 1.5rem;
}

.history-header h3 {
    font-size: 1.3rem;
    font-weight: 600;
    flex: 1;
}

.history-count {
    background: #f8f9fa;
    padding: 5px 15px;
    border-radius: 20px;
    font-size: 0.9rem;
    color: #666;
}

.history-list {
    min-height: 100px;
}

.empty-history {
    text-align: center;
    padding: 40px 20px;
    color: #999;
}

.empty-history i {
    font-size: 3rem;
    margin-bottom: 15px;
    opacity: 0.5;
}

.empty-history p {
    font-size: 1.1rem;
    margin-bottom: 5px;
}

.empty-hint {
    font-size: 0.9rem;
    color: #aaa;
}

.history-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 15px;
    border-bottom: 1px solid #f0f0f0;
    transition: background-color 0.3s ease;
}

.history-item:hover {
    background-color: #f8f9fa;
}

.history-item:last-child {
    border-bottom: none;
}

.history-time {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 500;
}

.history-time i {
    color: #f5576c;
}

.history-duration {
    color: #888;
    font-size: 0.9rem;
}

/* 进度条 */
.progress-container {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 30px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
}

.progress-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 20px;
    color: #667eea;
}

.progress-header i {
    font-size: 1.5rem;
}

.progress-header h3 {
    font-size: 1.3rem;
    font-weight: 600;
    flex: 1;
}

.progress-percent {
    font-size: 1.2rem;
    font-weight: 700;
    color: #f5576c;
}

.progress-bar {
    height: 12px;
    background: #f0f0f0;
    border-radius: 6px;
    overflow: hidden;
    margin-bottom: 10px;
}

.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, #4facfe 0%, #00f2fe 100%);
    border-radius: 6px;
    width: 0%;
    transition: width 0.5s ease;
}

.progress-text {
    text-align: center;
    color: #666;
    font-size: 0.9rem;
}

/* 提示信息 */
.message-toast {
    position: fixed;
    bottom: 30px;
    right: 30px;
    background: white;
    padding: 15px 25px;
    border-radius: 10px;
    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.15);
    display: none;
    align-items: center;
    gap: 10px;
    z-index: 1000;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

.toast-content i {
    color: #4CAF50;
    font-size: 1.2rem;
}

/* 确认对话框 */
.confirm-dialog {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 2000;
}

.dialog-content {
    background: white;
    padding: 30px;
    border-radius: 15px;
    max-width: 400px;
    width: 90%;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: scale(0.9);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

.dialog-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 20px;
    color: #f5576c;
}

.dialog-header i {
    font-size: 1.5rem;
}

.dialog-header h3 {
    font-size: 1.3rem;
    font-weight: 600;
}

.dialog-body {
    margin-bottom: 25px;
}

.dialog-body p {
    color: #666;
    line-height: 1.5;
}

.dialog-actions {
    display: flex;
    gap: 15px;
    justify-content: flex-end;
}

.btn-dialog-cancel, .btn-dialog-ok {
    padding: 10px 25px;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}

.btn-dialog-cancel {
    background: #f8f9fa;
    color: #666;
}

.btn-dialog-cancel:hover {
    background: #e9ecef;
}

.btn-dialog-ok {
    background: #f5576c;
    color: white;
}

.btn-dialog-ok:hover {
    background: #e04a5e;
}

/* 响应式设计 */
@media (max-width: 768px) {
    .app-container {
        padding: 10px;
    }

    .app-header {
        padding: 20px;
    }

    .app-header h1 {
        font-size: 2rem;
    }

    .stats-container {
        grid-template-columns: 1fr;
    }

    .actions-container {
        flex-direction: column;
    }

    .btn-primary, .btn-secondary {
        width: 100%;
    }

    .settings-content {
        grid-template-columns: 1fr;
    }

    .message-toast {
        left: 20px;
        right: 20px;
        bottom: 20px;
    }
}

@media (max-width: 480px) {
    .stat-value {
        font-size: 2.2rem;
    }

    .btn-primary, .btn-secondary {
        padding: 15px 25px;
        font-size: 1rem;
    }

    .input-group {
        flex-direction: column;
        align-items: stretch;
    }

    .input-unit {
        text-align: right;
    }
}

/* 动画效果 */
@keyframes pulse {
    0% { transform: scale(1); }
    50% { transform: scale(1.05); }
    100% { transform: scale(1); }
}

.pulse {
    animation: pulse 0.5s ease;
}

/* 加载状态 */
.loading {
    opacity: 0.7;
    pointer-events: none;
}

/* 成功状态 */
.success {
    color: #4CAF50 !important;
}

/* 警告状态 */
.warning {
    color: #FF9800 !important;
}

/* 危险状态 */
.danger {
    color: #f5576c !important;
}"}

